import pathlib, tempfile, subprocess, sys, json
with tempfile.TemporaryDirectory() as d:
 base = pathlib.Path(d) / "base.json"
 override = pathlib.Path(d) / "override.json"
 base.write_text(json.dumps({"service": {"port": 80, "remove": True}, "items": [1]}))
 override.write_text(json.dumps({"service": {"port": 443, "remove": None}, "items": [2, 3]}))
 for label, args, expected in [("layered success", [str(base), str(override)], 0), ("base-only success", [str(base)], 0), ("missing file error", [str(base), str(pathlib.Path(d) / "missing.json")], 2), ("argument error", [], 2)]:
  result = subprocess.run([sys.executable, "-m", "configkit", *args], capture_output=True, text=True)
  print(label, "status=", result.returncode, "stdout=", repr(result.stdout), "stderr=", repr(result.stderr))
  assert result.returncode == expected
  if expected:
   assert not result.stdout and result.stderr and "Traceback" not in result.stderr
  elif label == "layered success":
   assert json.loads(result.stdout) == {"service": {"port": 443}, "items": [2, 3]}
  else:
   assert json.loads(result.stdout) == {"service": {"port": 80, "remove": True}, "items": [1]}
